{
  "thesis": "投资判断：AI视频生成值得选择性布局，但不能把演示效果提升或融资热度当作商业化成立。优先考察能够提高可交付成片比例、降低完整制作成本并嵌入客户工作流的产品；对仅依靠通用文生视频能力、缺少分发与客户留存证据的公司保持谨慎。基础模型投资须额外证明持续技术优势及资本效率。上述判断是投资推论，不是已被收入、毛利或客户数据验证的结论。",
  "claims": [
    {
      "claim": "品类时机由技术可用性改善驱动，但规模化付费需求仍未得到证明。",
      "source": ["S004", "S005", "S008"],
      "locator": "S004 key_points第5项及summary末段；S005 summary第2段；S008 key_points第5项",
      "qualification": "控制工具与产品推出记录支持供给进步；工业化生产是行业观察中的判断，缺少客户采用率、收入与留存数据。不能据此断言市场已经成熟。"
    },
    {
      "claim": "2024年的产品集中发布与融资活动构成品类催化剂，而非市场规模估算依据。",
      "source": ["S005"],
      "locator": "summary第1段及第2段产品发布序列",
      "qualification": "约12亿元融资是该研究对Sora发布后五个月的统计说法，未提供底层交易清单。融资不能替代客户支出，不外推市场规模或增长率。"
    },
    {
      "claim": "市场应区分基础生成能力、创作控制与工作流，以及数字人、修复和剪辑等邻近应用，避免把不同需求混成一个市场。",
      "source": ["S004", "S005"],
      "locator": "S004 summary第1至3段；S005 summary第2段寻光定位",
      "qualification": "产品类型来自研究描述；按价值获取位置划分市场是作者分析。数字人、修复与长转短作为替代或邻近需求讨论，不默认纳入文生视频收入。"
    },
    {
      "claim": "Runway、Luma与可灵在历史评估中体现不同能力侧重，不能仅凭统一画质排名决定投资优先级。",
      "source": ["S004"],
      "locator": "summary第1段；key_points第1至2项",
      "qualification": "评估涉及Gen3、Kling 1.5等具体版本，缺少样本、测试方法和日期。只引用历史定位与差异，不作为2026年的当前排名。Pika掉队的说法也不能延伸为当前竞争结论。"
    },
    {
      "claim": "字节跳动即梦、快手可灵与阿里寻光分别体现精细控制、视频生成与全流程创作方向的竞争。",
      "source": ["S005"],
      "locator": "summary第2段即梦、可灵、寻光产品描述",
      "qualification": "均按2024年产品快照表述。即梦最长12秒、可灵续写最长3分钟等口径不同，不能直接比较一次生成质量。平台分发优势只能作为待验证假设，不能写成已实现的获客或转化优势。"
    },
    {
      "claim": "DiT与Transformer路线强化时序建模与语义控制，但架构趋同意味着采用同类架构本身不足以构成排他壁垒。",
      "source": ["S004", "S005"],
      "locator": "S004 key_points第1项及summary第2段；S005 summary第2段PixVerse V2描述",
      "qualification": "技术能力概述属于二手研究判断，不是受控实验结论。架构趋同削弱差异化是作者推论，不意味着各公司效果、训练效率或数据能力相同。"
    },
    {
      "claim": "长视频、清晰度、物理一致性和可控性共同决定交付难度；续写时长不能等同于持续叙事一致性。",
      "source": ["S004", "S005"],
      "locator": "S004 summary第2段；S005 key_points第3、5项及summary第1段",
      "qualification": "历史报告明确提及清晰度、时长和物理理解限制，但没有统一失败率。报告应把跨镜头角色一致性、修改稳定性列为尽调项目，而非断言各产品均已失败。"
    },
    {
      "claim": "技术壁垒应由稳定交付、推理效率、可编辑性和客户资产积累共同检验，而非只看最佳样片。",
      "source": ["S004", "S005", "S008"],
      "locator": "S004可控性工具描述；S005寻光图层编辑描述；S008 key_points第5项",
      "qualification": "这是据产品演进提出的投资框架。训练数据权利、反馈数据积累和切换成本均缺少公司级实证，需保留为待验证条件。"
    },
    {
      "claim": "同质化功能和免费生成额度可能压低基础生成的付费意愿，但现有证据不足以确认全行业价格战或毛利恶化。",
      "source": ["S005"],
      "locator": "key_points第3项；summary第2段Dream Machine免费额度描述",
      "qualification": "免费额度是历史获客策略，不等于当前价格或价格下降趋势。价格压力属于机制推演；不得编造每秒价格、算力成本和毛利率。"
    },
    {
      "claim": "通用大模型的资源投入与推理优化值得关注，但不能直接映射为视频模型成本优势。",
      "source": ["S009"],
      "locator": "summary腾讯算力投入描述及字节Ultra-Sparse Memory Network描述",
      "qualification": "相关投入含预测，架构优化针对特定推理场景且扩展能力待验证。正文仅用于提示平台资源竞争；不采用H20数量、企业本地部署降本比例推算视频生成经济性。"
    },
    {
      "claim": "商业化应按客户任务衡量完整成本，而不是把单次生成价格当作采购价值。",
      "source": ["S004", "S005", "S008"],
      "locator": "S004垂直应用及控制工具描述；S005工作流功能描述；S008 key_points第5项",
      "qualification": "建议指标为总生成支出、人工筛选修订、合规审核与集成成本除以验收成片数；这是尽调口径，不是已测得的数据。与传统制作比较时必须保持质量及交付要求一致。"
    },
    {
      "claim": "GTM应优先验证可重复、边界清晰的生产任务，再考虑扩大企业工作流覆盖。",
      "source": ["S004", "S005"],
      "locator": "S004 summary第3段细分应用；S005寻光全流程定位",
      "qualification": "从短素材版本制作等任务切入、以付费试点验证复购是作者建议。没有证据证明某一场景已拥有最佳获客成本或最高利润。"
    }
  ],
  "counterevidence": [
    {
      "challenge": "更多产品和融资可能主要反映技术示范效应与资本追逐，而非持续付费需求。",
      "basis": "S005记录融资与产品发布，却不提供客户收入、续费和使用频次。",
      "investment_effect": "不以融资额或生成次数估值；取得付费客户队列、复购和收入集中度后才提高商业化确信度。"
    },
    {
      "challenge": "更长、更清晰的生成结果仍可能因物理错误或修改不稳定而无法交付。",
      "basis": "S005的物理理解限制与清晰度、时长瓶颈；S004的控制工具迭代。",
      "investment_effect": "用包含失败样本和返工时间的完整项目测试替代精选样片；若完整成本不优于基线，否定效率溢价。"
    },
    {
      "challenge": "工作流产品也可能被基础模型原生编辑功能或平台捆绑替代。",
      "basis": "S005多家公司已增加编辑、尾帧控制和图层功能。",
      "investment_effect": "对应用层的偏好是有条件的；只有客户资产、协作流程或垂直交付能力产生可验证留存，才认可持续溢价。"
    },
    {
      "challenge": "基础模型公司可能通过显著质量领先和推理降本，比中间应用层获取更多价值。",
      "basis": "S004记载模型能力差异；S008将推理成本与延迟列为竞争变量。",
      "investment_effect": "若同任务实测出现持续能力领先、成本优势及客户直接采购，应上调模型层投资优先级。当前无法确认这种优势已存在。"
    },
    {
      "challenge": "需求增长未必带来收入或利润同步增长。",
      "basis": "S005同质化及免费额度；缺少价格、推理成本与毛利时间序列。",
      "investment_effect": "同时检查净成交价格、验收产出、全成本和客户留存，防止补贴及重复生成掩盖经济性。"
    },
    {
      "challenge": "版权、肖像授权、品牌安全和客户素材保密可能阻碍生产采用。",
      "basis": "四篇研究没有足够的合同、授权、合规或纠纷证据。",
      "investment_effect": "作为前瞻风险提出，不声称已发生具体违法事件；商业授权边界与责任分配应成为签约和投资前置核查项。"
    },
    {
      "challenge": "历史产品快照不足以支持当前胜负判断。",
      "basis": "S005主要覆盖2024年；S008标题指向2025年12月；S004与S009缺少明确日期，均无可核验原始链接。",
      "investment_effect": "明确时效与可核验性边界，不将Sora内测状态、旧版能力排名或融资洽谈写成当前事实，不给出目标估值。"
    }
  ],
  "parts": [
    {
      "number": 1,
      "headings": [
        "# AI视频生成市场投资Memo",
        "## 投资判断",
        "## 市场结构",
        "## 技术壁垒"
      ],
      "target_nonspace_characters": 1900,
      "coverage": [
        "开篇给出选择性投资建议、成立条件和证据边界：讨论国内外竞争，历史观察主要覆盖2024年至2025年12月，不宣称覆盖2026年最新市场。",
        "解释生成式AI视频品类从技术示范向生产工具演进的机会，同时区分供给改善和需求验证。",
        "比较Runway、Luma、可灵、字节跳动即梦、Sora、寻光与PixVerse的历史位置，围绕质量、控制、流程定位组织，不罗列当前排行榜。",
        "区分文生视频、图生视频、视频生视频和邻近应用，讨论模型层、创作工具层、工作流层的价值获取。",
        "说明多模态控制、时序一致性、数据与评测、推理效率如何影响交付，并解释为什么架构选择和最长时长不等于壁垒。",
        "保留模型层可能胜出的反向条件，为商业化部分衔接。"
      ],
      "citation_plan": "正文使用简短数字注释，主要对应《主流AI视频生成产品报告》《AI视频生成市场概况》；工业化趋势仅谨慎引用《AI行业月度观察202512》。不显示内部来源编号。",
      "depth_allocation": {
        "投资判断及范围说明": 450,
        "市场结构与关键公司": 750,
        "技术壁垒": 700
      }
    },
    {
      "number": 2,
      "headings": [
        "## 商业化",
        "## 风险与反证",
        "## 参考资料"
      ],
      "target_nonspace_characters": 1800,
      "coverage": [
        "解释同质化、免费额度和平台资源投入可能形成的价格压力，同时明确缺少实际价格曲线和公司单位经济性。",
        "提出按验收成片核算完整成本，纳入失败生成、人工返工、审核与集成；不设无依据的数值门槛。",
        "给出GTM建议：从有明确验收标准的重复生产任务切入，以付费试点验证节省成本、复购和留存，再扩展协作与集成。",
        "比较个人创作者自助获客与企业销售的推论性取舍：前者需验证付费及获客回收，后者需验证采购周期、集成负担与交付成本。",
        "分析质量可靠性、版权授权、隐私、平台捆绑和需求补贴风险；区别已记载的技术限制与前瞻商业风险。",
        "给出推翻主张的条件：完整成本不改善则降低投资兴趣；工作流无留存或溢价则撤销应用层偏好；模型持续领先且具成本优势则上调模型层优先级。",
        "结尾明确投资前需取得同任务测试、付费客户队列、净成交价及完整成本数据，当前不支持市场规模测算或估值结论。",
        "参考资料列出四篇研究标题与可识别时间信息，说明其为二手研究摘要，原始出处及方法未充分披露，不编造作者、链接和日期。"
      ],
      "citation_plan": "商业化引用前述产品研究；平台资源与推理优化仅有限引用《大模型行业近期市场信息：腾讯、阿里、字节及DeepSeek》。参考资料统一承接全文数字注释。",
      "depth_allocation": {
        "商业化与GTM": 900,
        "风险反证及投资行动": 650,
        "参考资料": 250
      },
      "whole_report_budget": "两部分合计目标3700个非空白字符，包含Markdown标题、标点、引用和参考资料；为2500—4500字符总限制保留余量。最终长度须在组装后核对，此处为预算而非实测。"
    }
  ]
}
